// Expected is one vector's ground truth, generated by
// test/gen/transcripts.py with the Python reference canonicalizer.
type Expected struct {
	Provider  string           `json:"provider"`
	Format    string           `json:"format"`
	Model     string           `json:"model"`
	Intents   []ExpectedIntent `json:"intents"`
	Unparsed  bool             `json:"unparsed"`
	DetailSub string           `json:"detail_substring"`
	Markers   []string         `json:"markers"`
}

type ExpectedIntent struct {
	ID          string `json:"intent_id"`
	Tool        string `json:"tool"`
	Executor    string `json:"executor"`
	InputSHA256 string `json:"input_sha256"`
	InputLen    int    `json:"input_len"`
}

const vectorRoot = "../../test/vectors/transcripts"

// loadVectors returns (wire, expected) pairs under dir.
func loadVectors(t *testing.T, dir string) []struct {
	name string
	wire []byte
	exp  Expected
} {
	t.Helper()
	base := filepath.Join(vectorRoot, dir)
	names, err := filepath.Glob(filepath.Join(base, "*.expected.json"))
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(names)
	var out []struct {
		name string
		wire []byte
		exp  Expected
	}
	for _, ef := range names {
		var e Expected
		b, err := os.ReadFile(ef)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(b, &e); err != nil {
			t.Fatalf("%s: %v", ef, err)
		}
		stem := strings.TrimSuffix(ef, ".expected.json")
		ext := ".json"
		if e.Format == "sse" {
			ext = ".sse"
		}
		wire, err := os.ReadFile(stem + ext)
		if err != nil {
			t.Fatal(err)
		}
		out = append(out, struct {
			name string
			wire []byte
			exp  Expected
		}{filepath.Base(stem), wire, e})
	}
	return out
}

func endpointFor(t *testing.T, provider string) Endpoint {
	t.Helper()
	switch provider {
	case "anthropic":
		return EndpointAnthropic
	case "responses":
		return EndpointResponses
	case "chat":
		return EndpointChat
	}
	t.Fatalf("provider %q", provider)
	return 0
}

// runParser feeds wire to a fresh parser in chunks sized by sizes
// (cycled) and collects completions, the parse error detail (if any)
// and the finish report.
func runParser(t *testing.T, ep Endpoint, format string, wire []byte, sizes []int) (
	comps []Completion, detail string, clean bool) {
	t.Helper()
	ct := "application/json"
	if format == "sse" {
		ct = "text/event-stream"
	}
	p, ok := NewResponseParser(ep, ct)
	if !ok {
		t.Fatalf("no parser for %v/%s", ep, ct)
	}
	pos := 0
	i := 0
	for pos < len(wire) {
		n := sizes[i%len(sizes)]
		i++
		if n <= 0 {
			n = 1
		}
		if pos+n > len(wire) {
			n = len(wire) - pos
		}
		cs, err := p.Feed(wire[pos : pos+n])
		comps = append(comps, cs...)
		pos += n
		if err != nil {
			if d, isP := ParseError(err); isP {
				detail = d
			} else {
				t.Fatalf("non-parse error: %v", err)
			}
			break
		}
	}
	d, c := p.Finish()
	if detail == "" && !c {
		detail = d
	}
	return comps, detail, c
}

// TestVectorsChunkIndependent is MM8.1: every vector's intents equal the
// ground truth under 1,000 random chunkings plus the boundary sizes.
func TestVectorsChunkIndependent(t *testing.T) {
	for _, dir := range []string{"anthropic", "openai"} {
		for _, v := range loadVectors(t, dir) {
			sizes := [][]int{{1}, {2}, {3}, {5}, {7}, {64}, {1024}, {1 << 20}}
			rng := rand.New(rand.NewSource(0xC0FFEE))
			for k := 0; k < 1000; k++ {
				a := 1 + rng.Intn(64)
				b := 1 + rng.Intn(2048)
				sizes = append(sizes, []int{a, b, 1 + rng.Intn(9)})
			}
			for si, sz := range sizes {
				comps, detail, _ := runParser(t, endpointFor(t, v.exp.Provider),
					v.exp.Format, v.wire, sz)
				if len(comps) != len(v.exp.Intents) {
					t.Fatalf("%s chunking %v: %d intents, want %d",
						v.name, sz, len(comps), len(v.exp.Intents))
				}
				for i, c := range comps {
					e := v.exp.Intents[i]
					if c.Intent.ID != e.ID || c.Intent.Tool != e.Tool ||
						c.Intent.Executor != e.Executor ||
						c.Intent.InputSHA256 != e.InputSHA256 ||
						len(c.Intent.InputRaw) != e.InputLen {
						t.Fatalf("%s chunking %v intent %d mismatch: %+v",
							v.name, sz, i, c.Intent)
					}
				}
				if (detail != "") != v.exp.Unparsed {
					t.Fatalf("%s chunking %v: unparsed=%v detail=%q",
						v.name, si, detail != "", detail)
				}
			}
		}
	}
}

// TestVectorsHoldPoints verifies hold points never exceed the fed prefix
// and land on the completing element (event first byte / element close).
func TestVectorsHoldPoints(t *testing.T) {
	for _, dir := range []string{"anthropic", "openai"} {
		for _, v := range loadVectors(t, dir) {
			comps, _, _ := runParser(t, endpointFor(t, v.exp.Provider),
				v.exp.Format, v.wire, []int{len(v.wire)})
			for _, c := range comps {
				if c.HoldAt < 0 || c.HoldAt >= int64(len(v.wire)) {
					t.Fatalf("%s: HoldAt %d outside [0,%d)",
						v.name, c.HoldAt, len(v.wire))
				}
			}
		}
	}
}

// TestParseMalformed proves malformed inputs never fabricate intents and
// always surface a parse failure (or a clean Finish where the shape is
// genuinely complete).
func TestParseMalformed(t *testing.T) {
	cases := []struct {
		name    string
		ep      Endpoint
		ct      string
		wire    string
		wantErr bool
	}{
		{"anth json truncated", EndpointAnthropic, "application/json",
			`{"id":"m","content":[{"type":"tool_use","id":"t1","name":"Bash","input":{"a"`, true},
		{"anth sse garbage event", EndpointAnthropic, "text/event-stream",
			"event: content_block_start\ndata: {not json}\n\n", true},
		{"anth sse orphan stop", EndpointAnthropic, "text/event-stream",
			"event: content_block_stop\ndata: {\"type\":\"content_block_stop\",\"index\":4}\n\n", true},
		{"anth sse cut partial line", EndpointAnthropic, "text/event-stream",
			"event: message_start\ndata: {\"type\":\"message_start\",\"message\":{\"model\":\"m\"}}\n\nevent: content_b", true},
		{"resp json truncated", EndpointResponses, "application/json",
			`{"output":[{"type":"function_call","id":"f"`, true},
		{"chat sse bad data", EndpointChat, "text/event-stream",
			"data: {oops}\n\n", true},
		{"resp sse orphan delta", EndpointResponses, "text/event-stream",
			"event: response.function_call_arguments.delta\ndata: {\"type\":\"x\",\"output_index\":2,\"delta\":\"a\"}\n\n", true},
	}
	for _, c := range cases {
		p, ok := NewResponseParser(c.ep, c.ct)
		if !ok {
			t.Fatalf("%s: no parser", c.name)
		}
		var comps []Completion
		var errSeen bool
		for _, ch := range [][]byte{[]byte(c.wire)} {
			cs, err := p.Feed(ch)
			comps = append(comps, cs...)
			if err != nil {
				errSeen = true
			}
		}
		d, clean := p.Finish()
		if !c.wantErr && errSeen {
			t.Fatalf("%s: unexpected error %v / %q", c.name, errSeen, d)
		}
		if c.wantErr && !errSeen && clean {
			t.Fatalf("%s: malformed input parsed cleanly", c.name)
		}
		_ = comps
	}
}

// TestParserMutationFuzz applies seeded mutations to every transcript
// (byte flips, truncation, duplication) and feeds them through the
// parser in arbitrary chunks: no panic, and every completed intent's ID
// must be a string that actually occurs in the wire — mutated or not,
// the parser only ever repeats stream bytes (MM8.4).
func TestParserMutationFuzz(t *testing.T) {
	rng := rand.New(rand.NewSource(0xF022))
	const iters = 40
	for _, dir := range []string{"anthropic", "openai"} {
		for _, v := range loadVectors(t, dir) {
			for i := 0; i < iters; i++ {
				wire := append([]byte(nil), v.wire...)
				switch rng.Intn(3) {
				case 0: // flip bytes
					for k := 1 + rng.Intn(8); k > 0; k-- {
						wire[rng.Intn(len(wire))] = byte(rng.Intn(256))
					}
				case 1: // truncate
					wire = wire[:1+rng.Intn(len(wire)-1)]
				case 2: // duplicate a span
					a, b := rng.Intn(len(wire)), rng.Intn(len(wire))
					if a > b {
						a, b = b, a
					}
					dup := append([]byte(nil), wire[a:b]...)
					wire = append(wire[:b], append(dup, wire[b:]...)...)
				}
				p, ok := NewResponseParser(endpointFor(t, v.exp.Provider), "text/event-stream")
				if v.exp.Format == "json" {
					p, ok = NewResponseParser(endpointFor(t, v.exp.Provider), "application/json")
				}
				if !ok {
					t.Fatal("no parser")
				}
				// JSON string decoding maps invalid UTF-8 to U+FFFD, so a
				// mutated-ID byte can legitimately surface sanitized.
				norm := strings.ToValidUTF8(string(wire), "�")
				pos := 0
				for pos < len(wire) {
					m := 1 + rng.Intn(512)
					if pos+m > len(wire) {
						m = len(wire) - pos
					}
					cs, err := p.Feed(wire[pos : pos+m])
					pos += m
					for _, c := range cs {
						if c.Intent != nil && !idInWire(c.Intent.ID, wire, norm) {
							t.Fatalf("%s mutation %d: fabricated intent id %q",
								v.name, i, c.Intent.ID)
						}
					}
					if err != nil {
						break
					}
				}
				p.Finish()
			}
		}
	}
}

// TestParserNeverFabricatesOnGarbage: random garbage must not produce a
// clean parse with intents it invented.
func TestParserNeverFabricatesOnGarbage(t *testing.T) {
	rng := rand.New(rand.NewSource(7))
	for _, ep := range []Endpoint{EndpointAnthropic, EndpointResponses, EndpointChat} {
		for i := 0; i < 2000; i++ {
			n := 1 + rng.Intn(400)
			b := make([]byte, n)
			for j := range b {
				b[j] = byte(rng.Intn(256))
			}
			p, _ := NewResponseParser(ep, "text/event-stream")
			pos := 0
			for pos < len(b) {
				m := 1 + rng.Intn(64)
				if pos+m > len(b) {
					m = len(b) - pos
				}
				cs, err := p.Feed(b[pos : pos+m])
				pos += m
				for _, c := range cs {
					// A garbage stream may "declare" only if the random
					// bytes coincidentally form a valid SSE event with a
					// valid block — vanishingly unlikely; flag it so the
					// check is honest.
					if c.Intent != nil && c.Intent.ID == "" {
						t.Fatalf("ep %v: intent with empty ID from garbage", ep)
					}
				}
				if err != nil {
					break
				}
			}
			p.Finish()
		}
	}
}

// FuzzResponseParser is the C8.1.6/C8.2.3 native fuzz target (the check
// suites run it at -fuzztime=600s). Every wire — corpus-seeded or
// fuzzer-mutated — is fed to all three endpoint parsers under both
// content types: no panic (the fuzzer reports it) and no fabricated
// intent — an intent's ID must be a string the wire actually carried
// (MM8.4).
func FuzzResponseParser(f *testing.F) {
	for _, dir := range []string{"anthropic", "openai"} {
		base := filepath.Join(vectorRoot, dir)
		for _, wire := range mustFuzzCorpus(f, base) {
			f.Add(wire)
		}
	}
	f.Fuzz(func(t *testing.T, wire []byte) {
		norm := strings.ToValidUTF8(string(wire), "�")
		for _, ep := range []Endpoint{EndpointAnthropic, EndpointResponses, EndpointChat} {
			for _, ct := range []string{"text/event-stream", "application/json"} {
				p, ok := NewResponseParser(ep, ct)
				if !ok {
					t.Fatalf("no parser for ep %v ct %q", ep, ct)
				}
				checkNoFabrication(t, p, wire, norm)
			}
		}
	})
}

// mustFuzzCorpus seeds the fuzzer with the transcript wires. It reads
// files directly because testing.F offers no helper injection point.
func mustFuzzCorpus(f *testing.F, base string) [][]byte {
	f.Helper()
	var out [][]byte
	for _, ext := range []string{"*.sse", "*.json"} {
		names, err := filepath.Glob(filepath.Join(base, ext))
		if err != nil {
			f.Fatal(err)
		}
		for _, n := range names {
			if strings.HasSuffix(n, ".expected.json") {
				continue
			}
			b, err := os.ReadFile(n)
			if err != nil {
				f.Fatal(err)
			}
			out = append(out, b)
		}
	}
	return out
}

// checkNoFabrication feeds wire to p in deterministic chunks — byte-wise
// on small inputs (maximal scanner stress), at line boundaries otherwise —
// and fails if any completed intent's ID is not a wire substring.
func checkNoFabrication(t *testing.T, p ResponseParser, wire []byte, norm string) {
	t.Helper()
	feed := func() (stop bool) {
		if len(wire) <= 4096 {
			for i := 0; i < len(wire); i++ {
				if stop = checkComps(t, p, wire[i:i+1], wire, norm); stop {
					return true
				}
			}
			return false
		}
		for pos := 0; pos < len(wire); {
			m := len(wire) - pos
			if i := bytes.IndexByte(wire[pos:], '\n'); i >= 0 {
				m = i + 1
			}
			if stop = checkComps(t, p, wire[pos:pos+m], wire, norm); stop {
				return true
			}
			pos += m
		}
		return false
	}
	_ = feed()
	p.Finish()
}

func checkComps(t *testing.T, p ResponseParser, chunk, wire []byte, norm string) (stop bool) {
	cs, err := p.Feed(chunk)
	for _, c := range cs {
		if c.Intent != nil && !idInWire(c.Intent.ID, wire, norm) {
			t.Fatalf("fabricated intent id %q", c.Intent.ID)
		}
	}
	return err != nil
}

// idInWire reports whether id could have been parsed out of wire. Every
// intent ID arrives as a JSON string value, so the check decodes every
// well-formed string token in the wire and looks for the ID inside one
// — checking the ID's re-encoded form instead would miss characters Go
// HTML-escapes (&, <, >) that wires legitimately carry unescaped. The
// raw wire is tried first as a fast path (also covers UTF-8
// sanitization, since norm is the ToValidUTF8 view of the wire).
func idInWire(id string, wire []byte, norm string) bool {
	if strings.Contains(norm, id) {
		return true
	}
	for i := 0; i+1 < len(wire); i++ {
		if wire[i] != '"' {
			continue
		}
		j := i + 1
		for ; j < len(wire); j++ {
			switch wire[j] {
			case '\\':
				j++
			case '"':
				goto quoted
			}
		}
		break
	quoted:
		var s string
		if json.Unmarshal(wire[i:j+1], &s) == nil && strings.Contains(s, id) {
			return true
		}
		i = j
	}
	return false
}
